function launcherHarness({ args = ['sq18b', '--single-writer-confirmed', '--fresh-attempt'],
  existing = [] } = {}) {
  const events = [], writes = [], copies = [], existsCalls = [], output = [];
  let spawned, error;
  const source = { selectedSpec: 'cypress/e2e/checkout/shipping-quote.cy.js', sourceId: 'synthetic-source',
    files: [{ path: 'cypress.shipping.config.cjs' }, { path: 'cypress/support/shipping-quote.js' }] };
  const fakeFs = {
    constants: { COPYFILE_EXCL: 1 },
    existsSync(target) { existsCalls.push(target); return existing.includes(target); },
    mkdirSync(target) { events.push({ action: 'mkdir', target }); },
    writeFileSync(target, data) { writes.push({ target, value: JSON.parse(data) }); events.push({ action: 'write', target }); },
    copyFileSync(from, to, mode) { copies.push({ from, to, mode }); events.push({ action: 'copy', to }); }
  };
  const fakeChild = {
    execFileSync(command, commandArgs, options) {
      same(command, 'git', 'Only existing ignore validation is invoked');
      same(commandArgs.slice(0, 3), ['check-ignore', '--quiet', path.join(args.includes('--fresh-attempt') ? freshRoot : legacyRoot, args.includes('--fresh-attempt') ? 'runtime' : 'sq18b', 'private-profile')], 'Runtime must be checked as private before launch');
      same(options.cwd, root, 'Ignore check stays in EZPost');
    },
    spawn(command, childArgs, options) {
      spawned = { command, args: childArgs, options };
      events.push({ action: 'spawn' });
      return { on() { return this; } };
    }
  };
  const context = vm.createContext({ __dirname: path.join(root, 'scripts'),
    process: { argv: ['node', 'open-shipping-quote.cjs', ...args], execPath: 'SYNTHETIC_NODE',
      env: { ELECTRON_RUN_AS_NODE: '1', PRIVATE_CANARY: canary } },
    console: { log(value) { output.push(value); }, error(value) { output.push(value); } },
    require(name) {
      if (name === 'node:fs') return fakeFs;
      if (name === 'node:path') return path;
      if (name === 'node:child_process') return fakeChild;
      same(name, './shipping-quote-source.cjs', 'No uncontrolled launcher dependency is loaded');
      return { spec: source.selectedSpec, freeze(value) { same(value, root, 'Manifest comes from EZPost root only'); return source; } };
    } });
  try {
    vm.runInContext(fs.readFileSync(path.join(root, 'scripts/open-shipping-quote.cjs'), 'utf8'), context,
      { filename: 'open-shipping-quote.cjs', timeout: 1000 });
  } catch (caught) { error = caught; }
  return { events, writes, copies, existsCalls, output, source, spawned, error };
}
